"use client"
import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"

/* Label type scale is the handoff's, not a step lower. `components.css:98`
   declares `.v-label{font-size:var(--fs-lead);font-weight:600;line-height:1.2}`
   with `.v-label.-sm{font-size:var(--fs-control)}` — 17px/1.2, and 14px for the
   small size. The candidate ran 14px/1.5 and 13px, so every label was a size
   small and half a line tall. `-sm` now takes its size from the authored class
   in label.css rather than restating a literal here. */
const LabelVariants=cva("v-label [var(--fs-lead)] [var(--fw-title)] [line-height:1.2] [box-shadow:none] [border:0] [background:none]",{variants:{variant:{"default":""},size:{"default":"","sm":"-sm"}},defaultVariants:{variant:"default",size:"default"}})
export type LabelProps=React.ComponentProps<"label"> & VariantProps<typeof LabelVariants> & { as?:React.ElementType }
export function Label({as:Tag="label",className,variant,size,...props}:LabelProps){return <Tag data-slot="label" data-part="root" className={cn(LabelVariants({variant,size}),className)} {...props}/>}

const StatsVariants=cva("v-stats [display:flex] [gap:var(--s-5)_var(--s-5)] [flex-wrap:wrap] [margin-top:var(--s-4)] [max-width:100%]",{variants:{variant:{"default":""},size:{"default":""}},defaultVariants:{variant:"default",size:"default"}})
export type StatsProps=React.ComponentProps<"div"> & VariantProps<typeof StatsVariants> & { as?:React.ElementType }
export function Stats({as:Tag="div",className,variant,size,...props}:StatsProps){return <Tag data-slot="label-stats" data-part="stats" className={cn(StatsVariants({variant,size}),className)} {...props}/>}

const StatVariants=cva("v-stat [display:grid] [gap:var(--s-1)] [min-width:0]",{variants:{variant:{"default":"","ul":"-ul [padding-bottom:var(--s-2)] [border-bottom:2px_solid_var(--wm,var(--v-text))]"},size:{"default":""}},defaultVariants:{variant:"default",size:"default"}})
export type StatProps=React.ComponentProps<"div"> & VariantProps<typeof StatVariants> & { as?:React.ElementType }
export function Stat({as:Tag="div",className,variant,size,...props}:StatProps){return <Tag data-slot="label-stat" data-part="stat" className={cn(StatVariants({variant,size}),className)} {...props}/>}

@layer cojeev-states {
/* Orthogonal authored class modifiers remain composable with CVA axes. */
.v-stat[data-slot].-ul{padding-bottom:var(--s-2);border-bottom:2px solid var(--wm,var(--v-text))}
/* `components.css:98` `.v-label.-sm{font-size:var(--fs-control)}` — 14px, the
   control size, not the 13px literal that had no token behind it. */
.v-label[data-slot].-sm{font-size:var(--fs-control)}

/* Authored contextual and pseudo-element rules, scoped to component-owned roots. */
.v-stats[data-slot]+.v-bars{margin-top:var(--s-6)}
.v-stats[data-slot]+.v-line{margin-top:var(--s-6)}
.v-stat[data-slot] span{white-space:normal}
.v-stat[data-slot] b{font-size:var(--fs-body);font-weight:var(--fw-bold);font-variant-numeric:tabular-nums;line-height:1.2}
.v-stat[data-slot] b .u{font-weight:var(--fw-regular);margin-left:3px}
.v-stat[data-slot] span{font-size:var(--fs-caps);letter-spacing:.06em;text-transform:uppercase;color:var(--muted-foreground)}
.v-stat[data-slot] b{font-size:var(--fs-reading)}
.v-stat[data-slot].-ul.-dashed{border-bottom-style:dashed}
@media (max-width:640px){.v-stats[data-slot]{gap:var(--s-4)}}
.v-label[data-slot]{box-shadow:none;border:0}
.v-stat[data-slot]{box-shadow:none;border:0}
.v-stats[data-slot]{box-shadow:none;border:0}

}
